flow.typescript:
// D5 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_flow.ts
//   합성 단어 데이터(화자별 분할) → Log-Mel → 작은 CNN → 학습 → 평가 → 혼동 행렬을 한 번에 (직접 만든 신경망)
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}

const WIN = 400; // 25 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금). 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMelFeat(y: Float32Array, nMels: number, hop: number, bank: Float64Array[] = melBank(SR, NFFT, nMels)): number[][] {
  // 1초 음성 -> Log-Mel [mel][frame]: 양끝을 거울처럼 접어 WIN/2 만큼 늘리고(center=True) 프레임 수 = 1 + floor(L / hop), 80 dB 아래는 잘라 냄
  const half = WIN / 2;
  const pad = new Float32Array(y.length + WIN);
  pad.set(y, half);
  for (let i = 0; i < half; i++) {
    pad[half - 1 - i] = y[i + 1];
    pad[half + y.length + i] = y[y.length - 2 - i];
  }
  const w = Float64Array.from({ length: WIN }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 주기형 Hann
  const frames = 1 + Math.floor(y.length / hop);
  const out = Array.from({ length: nMels }, () => new Array<number>(frames).fill(0));
  for (let m = 0; m < frames; m++) {
    const mag = magnitude(pad.subarray(m * hop, m * hop + WIN), NFFT, w);
    for (let b = 0; b < nMels; b++) out[b][m] = 10 * Math.log10(Math.max(bank[b].reduce((a, wt, k) => a + wt * mag[k] * mag[k], 0), 1e-10));
  }
  const top = Math.max(...out.map((r) => Math.max(...r)));
  return out.map((r) => r.map((v) => Math.max(v, top - 80)));
}

// ---- 아주 작은 CNN을 직접: [합성곱(3x3, 패딩 1) -> ReLU -> 최대 풀링 2x2] x 2 -> 평균 풀링 2x2 -> 한 줄로 펴기 -> 선형 -> softmax
interface T3 {
  c: number;
  h: number;
  w: number;
  d: Float64Array; // [채널][세로][가로]
}
interface Conv {
  cin: number;
  cout: number;
  w: Float64Array; // [cout][cin][3][3]
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Linear {
  nin: number;
  nout: number;
  w: Float64Array;
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Net {
  c1: Conv;
  c2: Conv;
  fc: Linear;
}

const t3 = (c: number, h: number, w: number): T3 => ({ c, h, w, d: new Float64Array(c * h * w) });

function newConv(cin: number, cout: number, rnd: () => number): Conv {
  const n = cout * cin * 9;
  const sd = Math.sqrt(2 / (cin * 9)); // He 초기값
  return { cin, cout, w: Float64Array.from({ length: n }, () => sd * gauss(rnd)), b: new Float64Array(cout), gw: new Float64Array(n), gb: new Float64Array(cout) };
}

function newNet(nClasses: number, rnd: () => number, ch: [number, number] = [6, 12]): Net {
  const nin = ch[1] * 2 * 5; // 입력이 16 x 41이면 마지막 평균 풀링 뒤 (채널, 2, 5)
  const sd = Math.sqrt(1 / nin);
  const fc: Linear = { nin, nout: nClasses, w: Float64Array.from({ length: nin * nClasses }, () => sd * gauss(rnd)), b: new Float64Array(nClasses), gw: new Float64Array(nin * nClasses), gb: new Float64Array(nClasses) };
  return { c1: newConv(1, ch[0], rnd), c2: newConv(ch[0], ch[1], rnd), fc };
}

function convFwd(p: Conv, x: T3): T3 {
  const y = t3(p.cout, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        let s = p.b[o];
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) s += p.w[((o * p.cin + c) * 3 + a) * 3 + b] * x.d[(c * x.h + ii) * x.w + jj];
            }
        y.d[(o * x.h + i) * x.w + j] = s;
      }
  return y;
}

function convBwd(p: Conv, x: T3, dy: T3): T3 {
  // 기울기: 가중치(gw) · 편향(gb)에 더하고, 앞 층으로 보낼 dx를 돌려준다
  const dx = t3(x.c, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        const g = dy.d[(o * x.h + i) * x.w + j];
        p.gb[o] += g;
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) {
                const wi = ((o * p.cin + c) * 3 + a) * 3 + b;
                p.gw[wi] += g * x.d[(c * x.h + ii) * x.w + jj];
                dx.d[(c * x.h + ii) * x.w + jj] += g * p.w[wi];
              }
            }
      }
  return dx;
}

const relu = (x: T3): T3 => ({ ...x, d: x.d.map((v) => Math.max(0, v)) });
const reluBwd = (x: T3, dy: T3): T3 => ({ ...dy, d: dy.d.map((g, i) => (x.d[i] > 0 ? g : 0)) });

function pool(x: T3): { y: T3; idx: Int32Array } {
  // 2x2 최대 풀링: 가장 큰 값만 남기고 그 위치를 기억(되돌릴 때 필요)
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  const idx = new Int32Array(y.d.length);
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let best = -1;
        for (let a = 0; a < 2; a++)
          for (let b = 0; b < 2; b++) {
            const at = (c * x.h + 2 * i + a) * x.w + 2 * j + b;
            if (best < 0 || x.d[at] > x.d[best]) best = at;
          }
        y.d[(c * y.h + i) * y.w + j] = x.d[best];
        idx[(c * y.h + i) * y.w + j] = best;
      }
  return { y, idx };
}

function poolBwd(idx: Int32Array, dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  idx.forEach((at, k) => (dx.d[at] += dy.d[k]));
  return dx;
}

function avgPool(x: T3): T3 {
  // 2x2 평균 풀링: 네 칸의 평균
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let s = 0;
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) s += x.d[(c * x.h + 2 * i + a) * x.w + 2 * j + b];
        y.d[(c * y.h + i) * y.w + j] = s / 4;
      }
  return y;
}

function avgPoolBwd(dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  for (let c = 0; c < dy.c; c++)
    for (let i = 0; i < dy.h; i++)
      for (let j = 0; j < dy.w; j++)
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) dx.d[(c * shape.h + 2 * i + a) * shape.w + 2 * j + b] += dy.d[(c * dy.h + i) * dy.w + j] / 4;
  return dx;
}

interface Cache {
  x: T3;
  a1: T3;
  r1: T3;
  p1: { y: T3; idx: Int32Array };
  a2: T3;
  r2: T3;
  p2: { y: T3; idx: Int32Array };
  p3: T3;
  g: Float64Array;
  logits: Float64Array;
}

function forward(net: Net, x: T3): Cache {
  const a1 = convFwd(net.c1, x);
  const r1 = relu(a1);
  const p1 = pool(r1);
  const a2 = convFwd(net.c2, p1.y);
  const r2 = relu(a2);
  const p2 = pool(r2);
  const p3 = avgPool(p2.y);
  const g = p3.d; // 한 줄로 펴기: (채널, 2, 5) -> 채널 x 10개
  const logits = Float64Array.from({ length: net.fc.nout }, (_, o) => net.fc.b[o] + g.reduce((s, v, k) => s + v * net.fc.w[o * net.fc.nin + k], 0));
  return { x, a1, r1, p1, a2, r2, p2, p3, g, logits };
}

function softmax(z: ArrayLike<number>): Float64Array {
  const m = Math.max(...Array.from(z)); // 가장 큰 값을 빼서 exp가 넘치지 않게
  const e = Float64Array.from(z, (v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

function backward(net: Net, c: Cache, dlogits: Float64Array): void {
  const fc = net.fc;
  const dg = new Float64Array(fc.nin);
  for (let o = 0; o < fc.nout; o++) {
    fc.gb[o] += dlogits[o];
    for (let k = 0; k < fc.nin; k++) {
      fc.gw[o * fc.nin + k] += dlogits[o] * c.g[k];
      dg[k] += dlogits[o] * fc.w[o * fc.nin + k];
    }
  }
  const dp3 = t3(c.p3.c, c.p3.h, c.p3.w);
  dp3.d.set(dg);
  const dp2 = avgPoolBwd(dp3, c.p2.y);
  const dr2 = poolBwd(c.p2.idx, dp2, c.r2);
  const dp1 = convBwd(net.c2, c.p1.y, reluBwd(c.a2, dr2));
  const dr1 = poolBwd(c.p1.idx, dp1, c.r1);
  convBwd(net.c1, c.x, reluBwd(c.a1, dr1));
}

function sgdStep(net: Net, lr: number, n: number): void {
  // 파라미터 -= 학습률 x 평균 기울기, 그리고 기울기 0으로
  for (const p of [net.c1, net.c2, net.fc]) {
    p.w.forEach((_, i) => ((p.w[i] -= (lr * p.gw[i]) / n), (p.gw[i] = 0)));
    p.b.forEach((_, i) => ((p.b[i] -= (lr * p.gb[i]) / n), (p.gb[i] = 0)));
  }
}

const MELS = 16; // TS는 계산을 줄이려고 작은 특징: 16 mel x 41 프레임 (hop 25 ms)
const HOPF = 400;
const BANK = melBank(SR, NFFT, MELS);

interface Sample {
  x: T3;
  y: number;
}

function makeData(perClass: number = 3): { train: Sample[]; val: Sample[]; test: Sample[]; mu: number; sd: number } {
  // 학습 · 검증 · 테스트 특징(학습 세트 기준으로 정규화)과 정답
  const raw = (spk: number[], seed: number): Sample[] => {
    const { X, y } = buildSet(spk, perClass, seed);
    return X.map((w, i) => {
      const f = logMelFeat(w, MELS, HOPF, BANK);
      return { x: { c: 1, h: MELS, w: f[0].length, d: Float64Array.from(f.flat()) }, y: y[i] };
    });
  };
  const train = raw(TRAIN_SPK, 1);
  const val = raw(VAL_SPK, 2);
  const test = raw(TEST_SPK, 3);
  const all = train.flatMap((s) => Array.from(s.x.d));
  const mu = all.reduce((a, v) => a + v, 0) / all.length;
  const sd = Math.sqrt(all.reduce((a, v) => a + (v - mu) ** 2, 0) / all.length);
  for (const s of [...train, ...val, ...test]) s.x = { ...s.x, d: s.x.d.map((v) => (v - mu) / sd) };
  return { train, val, test, mu, sd };
}

function evaluate(net: Net, set: Sample[]): { loss: number; acc: number; pred: number[] } {
  let loss = 0;
  const pred = set.map((s) => {
    const p = softmax(forward(net, s.x).logits);
    loss -= Math.log(p[s.y] + 1e-12) / set.length;
    return p.indexOf(Math.max(...p));
  });
  return { loss, acc: pred.filter((p, i) => p === set[i].y).length / set.length, pred };
}

function fit(net: Net, data: { train: Sample[]; val: Sample[] }, epochs: number, rnd: () => number, lr: number = 0.05, batch: number = 16, augment?: (x: T3) => T3, verbose: boolean = true): { trainAcc: number[]; valAcc: number[]; trainLoss: number[] } {
  const hist = { trainAcc: [] as number[], valAcc: [] as number[], trainLoss: [] as number[] };
  for (let ep = 1; ep <= epochs; ep++) {
    const order = data.train.map((_, i) => i).sort(() => rnd() - 0.5); // 섞기
    let loss = 0;
    let correct = 0;
    for (let i = 0; i < order.length; i += batch) {
      const ids = order.slice(i, i + batch);
      for (const k of ids) {
        const s = data.train[k];
        const c = forward(net, augment ? augment(s.x) : s.x); // 1. forward
        const p = softmax(c.logits);
        loss -= Math.log(p[s.y] + 1e-12); // 2. loss
        correct += p.indexOf(Math.max(...p)) === s.y ? 1 : 0;
        p[s.y] -= 1; // softmax + cross-entropy의 기울기 = 확률 - 정답(원-핫)
        backward(net, c, p); // 3. backward: 기울기 계산
      }
      sgdStep(net, lr, ids.length); // 4. 파라미터 업데이트
    }
    const v = evaluate(net, data.val);
    hist.trainLoss.push(loss / order.length);
    hist.trainAcc.push(correct / order.length);
    hist.valAcc.push(v.acc);
    if (verbose) console.log(`epoch ${String(ep).padStart(2)}/${epochs} | train loss ${(loss / order.length).toFixed(3)} acc ${((correct / order.length) * 100).toFixed(1)}% | val loss ${v.loss.toFixed(3)} acc ${(v.acc * 100).toFixed(1)}%`);
  }
  return hist;
}


const rnd = mulberry32(0);

// 1) 데이터: 화자가 겹치지 않게 나눈다
const tr = buildSet(TRAIN_SPK, 1, 1);
const te = buildSet(TEST_SPK, 1, 3);
check(!tr.spk.some((s) => te.spk.includes(s)), "학습과 테스트에 같은 화자가 있으면 안 돼요.");

// 2) 특징 -> 3) 모델
const data = makeData(3);
const x0 = data.train[0].x;
console.log(`특징 (${x0.c}, mel ${x0.h}, frame ${x0.w}) | 학습 ${data.train.length} · 검증 ${data.val.length} · 테스트 ${data.test.length}`);
check(x0.h === MELS && x0.w === 1 + Math.floor(SR / HOPF), "프레임 수 = 1 + L // hop 입니다.");
const net = newNet(KEYWORDS.length, rnd);
const nParams = [net.c1, net.c2, net.fc].reduce((a, p) => a + p.w.length + p.b.length, 0);
console.log(`작은 CNN 파라미터 ${nParams.toLocaleString()}개`);

// 4) 학습: forward -> loss -> backward -> step
const hist = fit(net, data, 15, rnd);
check(hist.trainLoss[hist.trainLoss.length - 1] < hist.trainLoss[0], "학습 손실이 줄어야 해요.");

// 5) 평가: 혼동 행렬 (행 = 정답, 열 = 예측)
const { pred } = evaluate(net, data.test);
const n = KEYWORDS.length;
const C = Array.from({ length: n }, () => new Array<number>(n).fill(0));
data.test.forEach((s, i) => C[s.y][pred[i]]++);
const trace = C.reduce((a, row, i) => a + row[i], 0);
const total = C.flat().reduce((a, v) => a + v, 0);
console.log(`테스트 정확도 ${((trace / total) * 100).toFixed(1)}% (대각합 ${trace} / 전체 ${total})`);
check(trace / total > 0.7 && total === data.test.length, "테스트 정확도가 70%를 넘어야 해요(무작위는 10%).");

data.typescript:
// D5 · Part 1 · 데이터셋과 분할 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_data.ts
//   합성 단어 데이터를 화자 단위로 학습 · 검증 · 테스트로 나누고(누수 방지) 클래스 균형과 1초 길이 맞추기(padOrTrim) 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}


// 화자 단위 분할: 같은 사람 목소리가 학습과 테스트에 함께 들어가면 점수가 부풀려진다(누수)
const tr = buildSet(TRAIN_SPK, 2, 1);
const va = buildSet(VAL_SPK, 2, 2);
const te = buildSet(TEST_SPK, 2, 3);
console.log(`학습 ${tr.y.length}개 (${new Set(tr.spk).size}명) · 검증 ${va.y.length}개 (${new Set(va.spk).size}명) · 테스트 ${te.y.length}개 (${new Set(te.spk).size}명)`);
const overlap = (a: number[], b: number[]): boolean => a.some((s) => b.includes(s));
check(!overlap(tr.spk, va.spk) && !overlap(tr.spk, te.spk) && !overlap(va.spk, te.spk), "세 묶음에 같은 화자가 있으면 안 돼요.");

// 클래스 균형: 단어마다 개수가 같은가
const counts = KEYWORDS.map((_, c) => tr.y.filter((v) => v === c).length);
console.log("학습 세트 단어별 개수:", KEYWORDS.map((k, c) => `${k}=${counts[c]}`).join(" "));
check(new Set(counts).size === 1 && tr.X.every((w) => w.length === SR), "단어마다 개수가 같고 클립은 모두 1초(16,000개)여야 해요.");

// 빈칸 실습 1의 답: 모자라면 0으로 채워 SR개로 (실제 녹음은 길이가 제각각)
function padOrTrim(y: Float32Array, n: number = SR): Float32Array {
  const out = new Float32Array(n);
  out.set(y.subarray(0, n));
  return out;
}
const r = mulberry32(0);
const lengths = Array.from({ length: 200 }, () => 8000 + Math.floor(16000 * r()));
const fixed = lengths.map((n) => padOrTrim(new Float32Array(n).fill(1)));
console.log(`원래 길이: 최소 ${Math.min(...lengths)} · 최대 ${Math.max(...lengths)} 샘플 | 1초 미만 ${((lengths.filter((n) => n < SR).length / lengths.length) * 100).toFixed(0)}%`);
check(fixed.every((f) => f.length === SR), "모든 클립이 정확히 16,000개가 돼야 해요.");

feature.typescript:
// D5 · Part 2 · 특징: 1초 음성 → Log-Mel 이미지 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_feature.ts
//   1초 합성 단어를 25 ms 창 · 10 ms hop Log-Mel (64 x 101)로 바꾸고 frame 수 공식(1 + L // hop)과 학습 세트 기준 정규화 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}

const WIN = 400; // 25 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금). 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMelFeat(y: Float32Array, nMels: number, hop: number, bank: Float64Array[] = melBank(SR, NFFT, nMels)): number[][] {
  // 1초 음성 -> Log-Mel [mel][frame]: 양끝을 거울처럼 접어 WIN/2 만큼 늘리고(center=True) 프레임 수 = 1 + floor(L / hop), 80 dB 아래는 잘라 냄
  const half = WIN / 2;
  const pad = new Float32Array(y.length + WIN);
  pad.set(y, half);
  for (let i = 0; i < half; i++) {
    pad[half - 1 - i] = y[i + 1];
    pad[half + y.length + i] = y[y.length - 2 - i];
  }
  const w = Float64Array.from({ length: WIN }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 주기형 Hann
  const frames = 1 + Math.floor(y.length / hop);
  const out = Array.from({ length: nMels }, () => new Array<number>(frames).fill(0));
  for (let m = 0; m < frames; m++) {
    const mag = magnitude(pad.subarray(m * hop, m * hop + WIN), NFFT, w);
    for (let b = 0; b < nMels; b++) out[b][m] = 10 * Math.log10(Math.max(bank[b].reduce((a, wt, k) => a + wt * mag[k] * mag[k], 0), 1e-10));
  }
  const top = Math.max(...out.map((r) => Math.max(...r)));
  return out.map((r) => r.map((v) => Math.max(v, top - 80)));
}


const HOP = 160; // 10 ms
const { X } = buildSet(TRAIN_SPK, 1, 1);
const feat = logMelFeat(X[0], 64, HOP);
const flat = feat.flat();
console.log(`예측: (64, ${1 + Math.floor(SR / HOP)}) | 실제: (${feat.length}, ${feat[0].length}) | 값 범위 ${Math.min(...flat).toFixed(1)} ~ ${Math.max(...flat).toFixed(1)} dB`);
check(feat.length === 64 && feat[0].length === 1 + Math.floor(SR / HOP) && Math.max(...flat) - Math.min(...flat) <= 80 + 1e-6, "frame 수 = 1 + L // hop = 101, 값은 80 dB 안이어야 해요.");

// 단어마다 에너지가 몰리는 mel 위치가 다르다: 평평한 낮은 소리 vs 높은 소리
const bank = melBank(SR, NFFT, 64);
const centroid = (w: Float32Array): number => {
  const f = logMelFeat(w, 64, HOP, bank);
  const rows = f.map((r) => r.reduce((a, v) => a + 10 ** (v / 10), 0));
  return rows.reduce((a, v, i) => a + v * i, 0) / rows.reduce((a, v) => a + v, 0); // 에너지 무게중심 mel 번호
};
const cLo = centroid(X[KEYWORDS.indexOf("flat_lo")]);
const cHi = centroid(X[KEYWORDS.indexOf("flat_hi")]);
console.log(`에너지 무게중심 mel 번호: flat_lo ${cLo.toFixed(1)} · flat_hi ${cHi.toFixed(1)} (높은 소리일수록 큼)`);
check(cHi > cLo + 8, "높은 소리는 높은 mel 번호에 에너지가 몰려요.");

// 학습 세트 기준 정규화: (X - mu) / sd 를 검증 · 테스트에도 같은 값으로
const all = X.flatMap((w) => logMelFeat(w, 64, HOP, bank).flat());
const mu = all.reduce((a, v) => a + v, 0) / all.length;
const sd = Math.sqrt(all.reduce((a, v) => a + (v - mu) ** 2, 0) / all.length);
const z = all.map((v) => (v - mu) / sd);
const zMean = z.reduce((a, v) => a + v, 0) / z.length;
const zSd = Math.sqrt(z.reduce((a, v) => a + (v - zMean) ** 2, 0) / z.length);
console.log(`정규화 전 평균 ${mu.toFixed(1)} 표준편차 ${sd.toFixed(1)} -> 후 평균 ${zMean.toFixed(3)} 표준편차 ${zSd.toFixed(3)}`);
check(Math.abs(zMean) < 1e-6 && Math.abs(zSd - 1) < 1e-6, "정규화 후 평균 0, 표준편차 1 이어야 해요.");

conv.typescript:
// D5 · Part 3 · CNN: 합성곱 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_conv.ts
//   3x3 합성곱을 직접 계산해 정의대로인지 확인, 출력 크기 공식 · 파라미터 수 공식, 세로 경계 검출 커널
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function conv2d(x: number[][][], k: number[][][][], padding: number = 1, stride: number = 1): number[][][] {
  // x [C_in][H][W], k [C_out][C_in][3][3] -> [C_out][H_out][W_out]: 3x3 창을 밀면서 곱해서 더한다
  const H = x[0].length;
  const W = x[0][0].length;
  const hOut = Math.floor((H + 2 * padding - 3) / stride) + 1;
  const wOut = Math.floor((W + 2 * padding - 3) / stride) + 1;
  return k.map((ko) =>
    Array.from({ length: hOut }, (_, i) =>
      Array.from({ length: wOut }, (_, j) => {
        let s = 0;
        for (let c = 0; c < x.length; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i * stride + a - padding;
              const jj = j * stride + b - padding;
              if (ii >= 0 && ii < H && jj >= 0 && jj < W) s += x[c][ii][jj] * ko[c][a][b]; // 밖은 0 (패딩)
            }
        return s;
      }),
    ),
  );
}

const rnd = mulberry32(0);
const x = [Array.from({ length: 12 }, () => Array.from({ length: 20 }, () => gauss(rnd)))];
const k = Array.from({ length: 4 }, () => [Array.from({ length: 3 }, () => Array.from({ length: 3 }, () => gauss(rnd)))]);

// 같은 위치를 다른 방법(원본 안쪽 한 점을 손으로 풀어 쓰기)으로 계산해 비교
const y = conv2d(x, k);
let hand = 0;
for (let a = 0; a < 3; a++) for (let b = 0; b < 3; b++) hand += x[0][5 + a - 1][7 + b - 1] * k[2][0][a][b];
console.log(`출력 모양 (${y.length}, ${y[0].length}, ${y[0][0].length}) | (채널 2, 5행 7열) = ${y[2][5][7].toFixed(6)} | 손으로 ${hand.toFixed(6)}`);
check(y.length === 4 && y[0].length === 12 && y[0][0].length === 20 && Math.abs(y[2][5][7] - hand) < 1e-12, "padding 1이면 크기가 그대로, 값은 손 계산과 같아야 해요.");

// 수식 검증: 출력 크기 = (H + 2P - K) // S + 1, 파라미터 수 = C_out x (C_in x K x K + 1)
const outSize = (h: number, kk: number = 3, p: number = 1, s: number = 1): number => Math.floor((h + 2 * p - kk) / s) + 1;
let ok = true;
for (const [h, p, s] of [[64, 1, 1], [64, 0, 1], [101, 1, 2], [40, 1, 1]]) {
  const img = [Array.from({ length: h }, () => new Array<number>(h).fill(0))];
  const real = conv2d(img, [[[[0, 0, 0], [0, 1, 0], [0, 0, 0]]]], p, s)[0].length;
  ok = ok && real === outSize(h, 3, p, s);
  console.log(`입력 ${h}, padding ${p}, stride ${s} -> 출력 ${real} (공식 ${outSize(h, 3, p, s)})`);
}
const params = 32 * (16 * 3 * 3 + 1);
console.log(`Conv(16 -> 32, 3x3) 파라미터 = 32 x (16 x 3 x 3 + 1) = ${params}개`);
check(ok && params === 4640, "출력 크기 공식이 실제와 같고 파라미터는 4,640개여야 해요.");

// 합성곱은 '무늬 탐지기': 세로 경계를 찾는 커널은 밝기가 바뀌는 열에서 가장 크게 반응한다
const img = [Array.from({ length: 8 }, () => Array.from({ length: 8 }, (_, j) => (j >= 4 ? 1 : 0)))];
const edge = [[[[-1, 0, 1], [-1, 0, 1], [-1, 0, 1]]]];
const resp = conv2d(img, edge, 0)[0];
console.log("세로 경계 커널 반응(첫 행):", resp[0].join(", "));
const best = resp[0].map(Math.abs).indexOf(Math.max(...resp[0].map(Math.abs)));
check([2, 3].includes(best) && resp.every((r) => r[0] === 0), "밝기가 바뀌는 열(3 ~ 4번)에서만 반응해야 해요.");

net.typescript:
// D5 · Part 3 · 모델 구조: KWSNet — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_net.ts
//   작은 CNN의 층마다 모양을 따라가고, 파라미터 수 공식(합성곱 · 선형)과 실제 비교
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];

// ---- 아주 작은 CNN을 직접: [합성곱(3x3, 패딩 1) -> ReLU -> 최대 풀링 2x2] x 2 -> 평균 풀링 2x2 -> 한 줄로 펴기 -> 선형 -> softmax
interface T3 {
  c: number;
  h: number;
  w: number;
  d: Float64Array; // [채널][세로][가로]
}
interface Conv {
  cin: number;
  cout: number;
  w: Float64Array; // [cout][cin][3][3]
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Linear {
  nin: number;
  nout: number;
  w: Float64Array;
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Net {
  c1: Conv;
  c2: Conv;
  fc: Linear;
}

const t3 = (c: number, h: number, w: number): T3 => ({ c, h, w, d: new Float64Array(c * h * w) });

function newConv(cin: number, cout: number, rnd: () => number): Conv {
  const n = cout * cin * 9;
  const sd = Math.sqrt(2 / (cin * 9)); // He 초기값
  return { cin, cout, w: Float64Array.from({ length: n }, () => sd * gauss(rnd)), b: new Float64Array(cout), gw: new Float64Array(n), gb: new Float64Array(cout) };
}

function newNet(nClasses: number, rnd: () => number, ch: [number, number] = [6, 12]): Net {
  const nin = ch[1] * 2 * 5; // 입력이 16 x 41이면 마지막 평균 풀링 뒤 (채널, 2, 5)
  const sd = Math.sqrt(1 / nin);
  const fc: Linear = { nin, nout: nClasses, w: Float64Array.from({ length: nin * nClasses }, () => sd * gauss(rnd)), b: new Float64Array(nClasses), gw: new Float64Array(nin * nClasses), gb: new Float64Array(nClasses) };
  return { c1: newConv(1, ch[0], rnd), c2: newConv(ch[0], ch[1], rnd), fc };
}

function convFwd(p: Conv, x: T3): T3 {
  const y = t3(p.cout, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        let s = p.b[o];
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) s += p.w[((o * p.cin + c) * 3 + a) * 3 + b] * x.d[(c * x.h + ii) * x.w + jj];
            }
        y.d[(o * x.h + i) * x.w + j] = s;
      }
  return y;
}

function convBwd(p: Conv, x: T3, dy: T3): T3 {
  // 기울기: 가중치(gw) · 편향(gb)에 더하고, 앞 층으로 보낼 dx를 돌려준다
  const dx = t3(x.c, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        const g = dy.d[(o * x.h + i) * x.w + j];
        p.gb[o] += g;
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) {
                const wi = ((o * p.cin + c) * 3 + a) * 3 + b;
                p.gw[wi] += g * x.d[(c * x.h + ii) * x.w + jj];
                dx.d[(c * x.h + ii) * x.w + jj] += g * p.w[wi];
              }
            }
      }
  return dx;
}

const relu = (x: T3): T3 => ({ ...x, d: x.d.map((v) => Math.max(0, v)) });
const reluBwd = (x: T3, dy: T3): T3 => ({ ...dy, d: dy.d.map((g, i) => (x.d[i] > 0 ? g : 0)) });

function pool(x: T3): { y: T3; idx: Int32Array } {
  // 2x2 최대 풀링: 가장 큰 값만 남기고 그 위치를 기억(되돌릴 때 필요)
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  const idx = new Int32Array(y.d.length);
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let best = -1;
        for (let a = 0; a < 2; a++)
          for (let b = 0; b < 2; b++) {
            const at = (c * x.h + 2 * i + a) * x.w + 2 * j + b;
            if (best < 0 || x.d[at] > x.d[best]) best = at;
          }
        y.d[(c * y.h + i) * y.w + j] = x.d[best];
        idx[(c * y.h + i) * y.w + j] = best;
      }
  return { y, idx };
}

function poolBwd(idx: Int32Array, dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  idx.forEach((at, k) => (dx.d[at] += dy.d[k]));
  return dx;
}

function avgPool(x: T3): T3 {
  // 2x2 평균 풀링: 네 칸의 평균
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let s = 0;
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) s += x.d[(c * x.h + 2 * i + a) * x.w + 2 * j + b];
        y.d[(c * y.h + i) * y.w + j] = s / 4;
      }
  return y;
}

function avgPoolBwd(dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  for (let c = 0; c < dy.c; c++)
    for (let i = 0; i < dy.h; i++)
      for (let j = 0; j < dy.w; j++)
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) dx.d[(c * shape.h + 2 * i + a) * shape.w + 2 * j + b] += dy.d[(c * dy.h + i) * dy.w + j] / 4;
  return dx;
}

interface Cache {
  x: T3;
  a1: T3;
  r1: T3;
  p1: { y: T3; idx: Int32Array };
  a2: T3;
  r2: T3;
  p2: { y: T3; idx: Int32Array };
  p3: T3;
  g: Float64Array;
  logits: Float64Array;
}

function forward(net: Net, x: T3): Cache {
  const a1 = convFwd(net.c1, x);
  const r1 = relu(a1);
  const p1 = pool(r1);
  const a2 = convFwd(net.c2, p1.y);
  const r2 = relu(a2);
  const p2 = pool(r2);
  const p3 = avgPool(p2.y);
  const g = p3.d; // 한 줄로 펴기: (채널, 2, 5) -> 채널 x 10개
  const logits = Float64Array.from({ length: net.fc.nout }, (_, o) => net.fc.b[o] + g.reduce((s, v, k) => s + v * net.fc.w[o * net.fc.nin + k], 0));
  return { x, a1, r1, p1, a2, r2, p2, p3, g, logits };
}

function softmax(z: ArrayLike<number>): Float64Array {
  const m = Math.max(...Array.from(z)); // 가장 큰 값을 빼서 exp가 넘치지 않게
  const e = Float64Array.from(z, (v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

function backward(net: Net, c: Cache, dlogits: Float64Array): void {
  const fc = net.fc;
  const dg = new Float64Array(fc.nin);
  for (let o = 0; o < fc.nout; o++) {
    fc.gb[o] += dlogits[o];
    for (let k = 0; k < fc.nin; k++) {
      fc.gw[o * fc.nin + k] += dlogits[o] * c.g[k];
      dg[k] += dlogits[o] * fc.w[o * fc.nin + k];
    }
  }
  const dp3 = t3(c.p3.c, c.p3.h, c.p3.w);
  dp3.d.set(dg);
  const dp2 = avgPoolBwd(dp3, c.p2.y);
  const dr2 = poolBwd(c.p2.idx, dp2, c.r2);
  const dp1 = convBwd(net.c2, c.p1.y, reluBwd(c.a2, dr2));
  const dr1 = poolBwd(c.p1.idx, dp1, c.r1);
  convBwd(net.c1, c.x, reluBwd(c.a1, dr1));
}

function sgdStep(net: Net, lr: number, n: number): void {
  // 파라미터 -= 학습률 x 평균 기울기, 그리고 기울기 0으로
  for (const p of [net.c1, net.c2, net.fc]) {
    p.w.forEach((_, i) => ((p.w[i] -= (lr * p.gw[i]) / n), (p.gw[i] = 0)));
    p.b.forEach((_, i) => ((p.b[i] -= (lr * p.gb[i]) / n), (p.gb[i] = 0)));
  }
}


const rnd = mulberry32(0);
const net = newNet(KEYWORDS.length, rnd);
const x = t3(1, 16, 41); // 이미지 1장: (1, mel 16, frame 41)
const c = forward(net, x);
const rows: Array<[string, string]> = [
  ["입력", `(${x.c}, ${x.h}, ${x.w})`],
  ["conv1 + ReLU", `(${c.a1.c}, ${c.a1.h}, ${c.a1.w})`],
  ["maxpool", `(${c.p1.y.c}, ${c.p1.y.h}, ${c.p1.y.w})`],
  ["conv2 + ReLU", `(${c.a2.c}, ${c.a2.h}, ${c.a2.w})`],
  ["maxpool", `(${c.p2.y.c}, ${c.p2.y.h}, ${c.p2.y.w})`],
  ["평균 풀링", `(${c.p3.c}, ${c.p3.h}, ${c.p3.w})`],
  ["한 줄로 펴기", `(${c.g.length},)`],
  ["linear", `(${c.logits.length},)`],
];
for (const [n, s] of rows) console.log(`${n.padEnd(14)} -> ${s}`);
check(c.logits.length === KEYWORDS.length && c.g.length === 12 * 2 * 5, "마지막 출력은 단어 10개 점수여야 해요.");

// 수식 검증: 출력 크기는 풀링마다 반으로(내림), 파라미터 = 합성곱 c_out(c_in x 9 + 1) + 선형 n_in x n_out + n_out (n_in = 12채널 x 2 x 5칸)
const h2 = Math.floor(Math.floor(16 / 2) / 2);
const w2 = Math.floor(Math.floor(41 / 2) / 2);
const chans = [1, 6, 12];
const formula = chans.slice(1).reduce((a, co, i) => a + co * (chans[i] * 9 + 1), 0) + 12 * 2 * 5 * KEYWORDS.length + KEYWORDS.length;
const real = [net.c1, net.c2, net.fc].reduce((a, p) => a + p.w.length + p.b.length, 0);
console.log(`풀링 2번 뒤 크기: 16 x 41 -> ${h2} x ${w2} | 파라미터 공식 ${formula.toLocaleString()}개 | 실제 ${real.toLocaleString()}개`);
check(c.p2.y.h === h2 && c.p2.y.w === w2 && formula === real, "크기 계산(4 x 10)과 파라미터 수 공식이 실제와 같아야 해요.");

softmax.typescript:
// D5 · Part 3 · softmax와 cross-entropy — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_softmax.ts
//   softmax · cross-entropy 를 식 그대로 계산하고, 기울기 = 확률 − 정답(원-핫)을 수치 미분과 비교, 숫자가 커도 안 넘치는 안정화
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function softmax(z: number[]): number[] {
  const m = Math.max(...z); // 가장 큰 값을 빼서 exp가 넘치지 않게 (결과는 같음)
  const e = z.map((v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

const crossEntropy = (z: number[], y: number): number => -Math.log(softmax(z)[y]);

// 빈칸 실습 5의 답: 클래스 방향으로 합한다 (행마다 확률 합 = 1)
const zs = [[2.0, 1.0, 0.1, -1.0], [0.5, 0.5, 0.5, 0.5]]; // (B=2, 클래스 4개) 점수
const ys = [0, 3]; // 정답
const probs = zs.map(softmax);
const ce = ys.reduce((a, y, i) => a + crossEntropy(zs[i], y), 0) / ys.length;
console.log("softmax:", probs.map((p) => `[${p.map((v) => v.toFixed(3)).join(", ")}]`).join(" "), "| 행 합:", probs.map((p) => p.reduce((a, v) => a + v, 0).toFixed(3)).join(", "));
console.log(`CE ${ce.toFixed(4)} (정답 확률의 -log 평균)`);
check(probs.every((p) => Math.abs(p.reduce((a, v) => a + v, 0) - 1) < 1e-12) && Math.abs(ce - (-Math.log(probs[0][0]) - Math.log(probs[1][3])) / 2) < 1e-12, "행 합은 1, CE는 정답 확률의 -log 평균이어야 해요.");

// 기울기: dL/dz = softmax - 원-핫 (아주 조금 흔들어 보는 수치 미분과 같다)
let worst = 0;
zs.forEach((z, i) => {
  probs[i].forEach((p, k) => {
    const eps = 1e-6;
    const up = z.map((v, j) => (j === k ? v + eps : v));
    const dn = z.map((v, j) => (j === k ? v - eps : v));
    const numeric = (crossEntropy(up, ys[i]) - crossEntropy(dn, ys[i])) / (2 * eps);
    worst = Math.max(worst, Math.abs(numeric - (p - (k === ys[i] ? 1 : 0))));
  });
});
console.log(`수치 미분과 (확률 - 원-핫)의 최대 차이 ${worst.toExponential(2)}`);
check(worst < 1e-6, "기울기는 (확률 - 정답 원-핫) 이어야 해요.");

// 숫자가 크면 exp가 넘친다 -> 가장 큰 값을 빼고 계산해도 결과는 같다
const big = [1000, 1001, 1002];
const naiveSum = big.reduce((a, v) => a + Math.exp(v), 0);
const naive = big.map((v) => Math.exp(v) / naiveSum);
const stable = softmax(big);
console.log("그냥 계산:", naive.map((v) => String(v)).join(", "), "| 안정화:", stable.map((v) => v.toFixed(3)).join(", "));
check(naive.some((v) => Number.isNaN(v)) && Math.abs(stable[2] - 0.665) < 1e-3, "그냥 계산은 넘쳐서 NaN, 안정화한 값은 0.665 근처여야 해요.");

// 학습 시작 때 loss: 아직 아무것도 모르면 10개 단어를 똑같이 찍는다 -> -log(1/10)
const start = -Math.log(1 / 10);
console.log(`무작위 추측 loss = -log(1/10) = ${start.toFixed(4)}`);
check(Math.abs(start - 2.3026) < 1e-3, "10개 단어 무작위 추측의 loss는 2.3026 입니다.");

train.typescript:
// D5 · Part 4 · 학습: forward → loss → backward → step — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_train.ts
//   학습률이 너무 작으면 거의 안 배우고 적당하면 loss가 줄어드는 학습 곡선, train − val 정확도 차이로 과적합 보기
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}

const WIN = 400; // 25 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금). 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMelFeat(y: Float32Array, nMels: number, hop: number, bank: Float64Array[] = melBank(SR, NFFT, nMels)): number[][] {
  // 1초 음성 -> Log-Mel [mel][frame]: 양끝을 거울처럼 접어 WIN/2 만큼 늘리고(center=True) 프레임 수 = 1 + floor(L / hop), 80 dB 아래는 잘라 냄
  const half = WIN / 2;
  const pad = new Float32Array(y.length + WIN);
  pad.set(y, half);
  for (let i = 0; i < half; i++) {
    pad[half - 1 - i] = y[i + 1];
    pad[half + y.length + i] = y[y.length - 2 - i];
  }
  const w = Float64Array.from({ length: WIN }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 주기형 Hann
  const frames = 1 + Math.floor(y.length / hop);
  const out = Array.from({ length: nMels }, () => new Array<number>(frames).fill(0));
  for (let m = 0; m < frames; m++) {
    const mag = magnitude(pad.subarray(m * hop, m * hop + WIN), NFFT, w);
    for (let b = 0; b < nMels; b++) out[b][m] = 10 * Math.log10(Math.max(bank[b].reduce((a, wt, k) => a + wt * mag[k] * mag[k], 0), 1e-10));
  }
  const top = Math.max(...out.map((r) => Math.max(...r)));
  return out.map((r) => r.map((v) => Math.max(v, top - 80)));
}

// ---- 아주 작은 CNN을 직접: [합성곱(3x3, 패딩 1) -> ReLU -> 최대 풀링 2x2] x 2 -> 평균 풀링 2x2 -> 한 줄로 펴기 -> 선형 -> softmax
interface T3 {
  c: number;
  h: number;
  w: number;
  d: Float64Array; // [채널][세로][가로]
}
interface Conv {
  cin: number;
  cout: number;
  w: Float64Array; // [cout][cin][3][3]
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Linear {
  nin: number;
  nout: number;
  w: Float64Array;
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Net {
  c1: Conv;
  c2: Conv;
  fc: Linear;
}

const t3 = (c: number, h: number, w: number): T3 => ({ c, h, w, d: new Float64Array(c * h * w) });

function newConv(cin: number, cout: number, rnd: () => number): Conv {
  const n = cout * cin * 9;
  const sd = Math.sqrt(2 / (cin * 9)); // He 초기값
  return { cin, cout, w: Float64Array.from({ length: n }, () => sd * gauss(rnd)), b: new Float64Array(cout), gw: new Float64Array(n), gb: new Float64Array(cout) };
}

function newNet(nClasses: number, rnd: () => number, ch: [number, number] = [6, 12]): Net {
  const nin = ch[1] * 2 * 5; // 입력이 16 x 41이면 마지막 평균 풀링 뒤 (채널, 2, 5)
  const sd = Math.sqrt(1 / nin);
  const fc: Linear = { nin, nout: nClasses, w: Float64Array.from({ length: nin * nClasses }, () => sd * gauss(rnd)), b: new Float64Array(nClasses), gw: new Float64Array(nin * nClasses), gb: new Float64Array(nClasses) };
  return { c1: newConv(1, ch[0], rnd), c2: newConv(ch[0], ch[1], rnd), fc };
}

function convFwd(p: Conv, x: T3): T3 {
  const y = t3(p.cout, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        let s = p.b[o];
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) s += p.w[((o * p.cin + c) * 3 + a) * 3 + b] * x.d[(c * x.h + ii) * x.w + jj];
            }
        y.d[(o * x.h + i) * x.w + j] = s;
      }
  return y;
}

function convBwd(p: Conv, x: T3, dy: T3): T3 {
  // 기울기: 가중치(gw) · 편향(gb)에 더하고, 앞 층으로 보낼 dx를 돌려준다
  const dx = t3(x.c, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        const g = dy.d[(o * x.h + i) * x.w + j];
        p.gb[o] += g;
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) {
                const wi = ((o * p.cin + c) * 3 + a) * 3 + b;
                p.gw[wi] += g * x.d[(c * x.h + ii) * x.w + jj];
                dx.d[(c * x.h + ii) * x.w + jj] += g * p.w[wi];
              }
            }
      }
  return dx;
}

const relu = (x: T3): T3 => ({ ...x, d: x.d.map((v) => Math.max(0, v)) });
const reluBwd = (x: T3, dy: T3): T3 => ({ ...dy, d: dy.d.map((g, i) => (x.d[i] > 0 ? g : 0)) });

function pool(x: T3): { y: T3; idx: Int32Array } {
  // 2x2 최대 풀링: 가장 큰 값만 남기고 그 위치를 기억(되돌릴 때 필요)
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  const idx = new Int32Array(y.d.length);
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let best = -1;
        for (let a = 0; a < 2; a++)
          for (let b = 0; b < 2; b++) {
            const at = (c * x.h + 2 * i + a) * x.w + 2 * j + b;
            if (best < 0 || x.d[at] > x.d[best]) best = at;
          }
        y.d[(c * y.h + i) * y.w + j] = x.d[best];
        idx[(c * y.h + i) * y.w + j] = best;
      }
  return { y, idx };
}

function poolBwd(idx: Int32Array, dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  idx.forEach((at, k) => (dx.d[at] += dy.d[k]));
  return dx;
}

function avgPool(x: T3): T3 {
  // 2x2 평균 풀링: 네 칸의 평균
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let s = 0;
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) s += x.d[(c * x.h + 2 * i + a) * x.w + 2 * j + b];
        y.d[(c * y.h + i) * y.w + j] = s / 4;
      }
  return y;
}

function avgPoolBwd(dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  for (let c = 0; c < dy.c; c++)
    for (let i = 0; i < dy.h; i++)
      for (let j = 0; j < dy.w; j++)
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) dx.d[(c * shape.h + 2 * i + a) * shape.w + 2 * j + b] += dy.d[(c * dy.h + i) * dy.w + j] / 4;
  return dx;
}

interface Cache {
  x: T3;
  a1: T3;
  r1: T3;
  p1: { y: T3; idx: Int32Array };
  a2: T3;
  r2: T3;
  p2: { y: T3; idx: Int32Array };
  p3: T3;
  g: Float64Array;
  logits: Float64Array;
}

function forward(net: Net, x: T3): Cache {
  const a1 = convFwd(net.c1, x);
  const r1 = relu(a1);
  const p1 = pool(r1);
  const a2 = convFwd(net.c2, p1.y);
  const r2 = relu(a2);
  const p2 = pool(r2);
  const p3 = avgPool(p2.y);
  const g = p3.d; // 한 줄로 펴기: (채널, 2, 5) -> 채널 x 10개
  const logits = Float64Array.from({ length: net.fc.nout }, (_, o) => net.fc.b[o] + g.reduce((s, v, k) => s + v * net.fc.w[o * net.fc.nin + k], 0));
  return { x, a1, r1, p1, a2, r2, p2, p3, g, logits };
}

function softmax(z: ArrayLike<number>): Float64Array {
  const m = Math.max(...Array.from(z)); // 가장 큰 값을 빼서 exp가 넘치지 않게
  const e = Float64Array.from(z, (v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

function backward(net: Net, c: Cache, dlogits: Float64Array): void {
  const fc = net.fc;
  const dg = new Float64Array(fc.nin);
  for (let o = 0; o < fc.nout; o++) {
    fc.gb[o] += dlogits[o];
    for (let k = 0; k < fc.nin; k++) {
      fc.gw[o * fc.nin + k] += dlogits[o] * c.g[k];
      dg[k] += dlogits[o] * fc.w[o * fc.nin + k];
    }
  }
  const dp3 = t3(c.p3.c, c.p3.h, c.p3.w);
  dp3.d.set(dg);
  const dp2 = avgPoolBwd(dp3, c.p2.y);
  const dr2 = poolBwd(c.p2.idx, dp2, c.r2);
  const dp1 = convBwd(net.c2, c.p1.y, reluBwd(c.a2, dr2));
  const dr1 = poolBwd(c.p1.idx, dp1, c.r1);
  convBwd(net.c1, c.x, reluBwd(c.a1, dr1));
}

function sgdStep(net: Net, lr: number, n: number): void {
  // 파라미터 -= 학습률 x 평균 기울기, 그리고 기울기 0으로
  for (const p of [net.c1, net.c2, net.fc]) {
    p.w.forEach((_, i) => ((p.w[i] -= (lr * p.gw[i]) / n), (p.gw[i] = 0)));
    p.b.forEach((_, i) => ((p.b[i] -= (lr * p.gb[i]) / n), (p.gb[i] = 0)));
  }
}

const MELS = 16; // TS는 계산을 줄이려고 작은 특징: 16 mel x 41 프레임 (hop 25 ms)
const HOPF = 400;
const BANK = melBank(SR, NFFT, MELS);

interface Sample {
  x: T3;
  y: number;
}

function makeData(perClass: number = 3): { train: Sample[]; val: Sample[]; test: Sample[]; mu: number; sd: number } {
  // 학습 · 검증 · 테스트 특징(학습 세트 기준으로 정규화)과 정답
  const raw = (spk: number[], seed: number): Sample[] => {
    const { X, y } = buildSet(spk, perClass, seed);
    return X.map((w, i) => {
      const f = logMelFeat(w, MELS, HOPF, BANK);
      return { x: { c: 1, h: MELS, w: f[0].length, d: Float64Array.from(f.flat()) }, y: y[i] };
    });
  };
  const train = raw(TRAIN_SPK, 1);
  const val = raw(VAL_SPK, 2);
  const test = raw(TEST_SPK, 3);
  const all = train.flatMap((s) => Array.from(s.x.d));
  const mu = all.reduce((a, v) => a + v, 0) / all.length;
  const sd = Math.sqrt(all.reduce((a, v) => a + (v - mu) ** 2, 0) / all.length);
  for (const s of [...train, ...val, ...test]) s.x = { ...s.x, d: s.x.d.map((v) => (v - mu) / sd) };
  return { train, val, test, mu, sd };
}

function evaluate(net: Net, set: Sample[]): { loss: number; acc: number; pred: number[] } {
  let loss = 0;
  const pred = set.map((s) => {
    const p = softmax(forward(net, s.x).logits);
    loss -= Math.log(p[s.y] + 1e-12) / set.length;
    return p.indexOf(Math.max(...p));
  });
  return { loss, acc: pred.filter((p, i) => p === set[i].y).length / set.length, pred };
}

function fit(net: Net, data: { train: Sample[]; val: Sample[] }, epochs: number, rnd: () => number, lr: number = 0.05, batch: number = 16, augment?: (x: T3) => T3, verbose: boolean = true): { trainAcc: number[]; valAcc: number[]; trainLoss: number[] } {
  const hist = { trainAcc: [] as number[], valAcc: [] as number[], trainLoss: [] as number[] };
  for (let ep = 1; ep <= epochs; ep++) {
    const order = data.train.map((_, i) => i).sort(() => rnd() - 0.5); // 섞기
    let loss = 0;
    let correct = 0;
    for (let i = 0; i < order.length; i += batch) {
      const ids = order.slice(i, i + batch);
      for (const k of ids) {
        const s = data.train[k];
        const c = forward(net, augment ? augment(s.x) : s.x); // 1. forward
        const p = softmax(c.logits);
        loss -= Math.log(p[s.y] + 1e-12); // 2. loss
        correct += p.indexOf(Math.max(...p)) === s.y ? 1 : 0;
        p[s.y] -= 1; // softmax + cross-entropy의 기울기 = 확률 - 정답(원-핫)
        backward(net, c, p); // 3. backward: 기울기 계산
      }
      sgdStep(net, lr, ids.length); // 4. 파라미터 업데이트
    }
    const v = evaluate(net, data.val);
    hist.trainLoss.push(loss / order.length);
    hist.trainAcc.push(correct / order.length);
    hist.valAcc.push(v.acc);
    if (verbose) console.log(`epoch ${String(ep).padStart(2)}/${epochs} | train loss ${(loss / order.length).toFixed(3)} acc ${((correct / order.length) * 100).toFixed(1)}% | val loss ${v.loss.toFixed(3)} acc ${(v.acc * 100).toFixed(1)}%`);
  }
  return hist;
}


const data = makeData(3);

// 학습률 비교: 너무 작으면 한 걸음이 짧아 거의 안 움직인다 (각각 4 epoch)
const last: Record<string, number> = {};
for (const lr of [0.0005, 0.05]) {
  const h = fit(newNet(KEYWORDS.length, mulberry32(0)), data, 4, mulberry32(1), lr, 16, undefined, false);
  last[lr] = h.trainLoss[h.trainLoss.length - 1];
  console.log(`lr=${lr}: 4 epoch 뒤 train loss ${last[lr].toFixed(3)}`);
}
check(last[0.05] < last[0.0005] - 0.3, "적당한 학습률이 너무 작은 학습률보다 loss가 훨씬 낮아야 해요.");

// 본 학습: 15 epoch
const net = newNet(KEYWORDS.length, mulberry32(0));
const hist = fit(net, data, 15, mulberry32(1));
const gap = hist.trainAcc[hist.trainAcc.length - 1] - hist.valAcc[hist.valAcc.length - 1];
console.log(`마지막 epoch: train ${(hist.trainAcc[hist.trainAcc.length - 1] * 100).toFixed(1)}% · val ${(hist.valAcc[hist.valAcc.length - 1] * 100).toFixed(1)}% -> 차이 ${gap >= 0 ? "+" : ""}${(gap * 100).toFixed(1)}%${gap > 0.05 ? "  (차이가 크면 과적합 신호)" : ""}`);
check(hist.trainLoss[hist.trainLoss.length - 1] < hist.trainLoss[0] * 0.6 && hist.valAcc[hist.valAcc.length - 1] > 0.7, "손실은 크게 줄고 검증 정확도는 70%를 넘어야 해요.");

confusion.typescript:
// D5 · Part 5 · 평가: 정확도와 혼동 행렬 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_confusion.ts
//   학습한 CNN으로 테스트 세트를 예측해 혼동 행렬 · 정밀도 · 재현율 · F1 계산, 가장 많이 헷갈린 쌍 찾기
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}

const WIN = 400; // 25 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금). 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMelFeat(y: Float32Array, nMels: number, hop: number, bank: Float64Array[] = melBank(SR, NFFT, nMels)): number[][] {
  // 1초 음성 -> Log-Mel [mel][frame]: 양끝을 거울처럼 접어 WIN/2 만큼 늘리고(center=True) 프레임 수 = 1 + floor(L / hop), 80 dB 아래는 잘라 냄
  const half = WIN / 2;
  const pad = new Float32Array(y.length + WIN);
  pad.set(y, half);
  for (let i = 0; i < half; i++) {
    pad[half - 1 - i] = y[i + 1];
    pad[half + y.length + i] = y[y.length - 2 - i];
  }
  const w = Float64Array.from({ length: WIN }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 주기형 Hann
  const frames = 1 + Math.floor(y.length / hop);
  const out = Array.from({ length: nMels }, () => new Array<number>(frames).fill(0));
  for (let m = 0; m < frames; m++) {
    const mag = magnitude(pad.subarray(m * hop, m * hop + WIN), NFFT, w);
    for (let b = 0; b < nMels; b++) out[b][m] = 10 * Math.log10(Math.max(bank[b].reduce((a, wt, k) => a + wt * mag[k] * mag[k], 0), 1e-10));
  }
  const top = Math.max(...out.map((r) => Math.max(...r)));
  return out.map((r) => r.map((v) => Math.max(v, top - 80)));
}

// ---- 아주 작은 CNN을 직접: [합성곱(3x3, 패딩 1) -> ReLU -> 최대 풀링 2x2] x 2 -> 평균 풀링 2x2 -> 한 줄로 펴기 -> 선형 -> softmax
interface T3 {
  c: number;
  h: number;
  w: number;
  d: Float64Array; // [채널][세로][가로]
}
interface Conv {
  cin: number;
  cout: number;
  w: Float64Array; // [cout][cin][3][3]
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Linear {
  nin: number;
  nout: number;
  w: Float64Array;
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Net {
  c1: Conv;
  c2: Conv;
  fc: Linear;
}

const t3 = (c: number, h: number, w: number): T3 => ({ c, h, w, d: new Float64Array(c * h * w) });

function newConv(cin: number, cout: number, rnd: () => number): Conv {
  const n = cout * cin * 9;
  const sd = Math.sqrt(2 / (cin * 9)); // He 초기값
  return { cin, cout, w: Float64Array.from({ length: n }, () => sd * gauss(rnd)), b: new Float64Array(cout), gw: new Float64Array(n), gb: new Float64Array(cout) };
}

function newNet(nClasses: number, rnd: () => number, ch: [number, number] = [6, 12]): Net {
  const nin = ch[1] * 2 * 5; // 입력이 16 x 41이면 마지막 평균 풀링 뒤 (채널, 2, 5)
  const sd = Math.sqrt(1 / nin);
  const fc: Linear = { nin, nout: nClasses, w: Float64Array.from({ length: nin * nClasses }, () => sd * gauss(rnd)), b: new Float64Array(nClasses), gw: new Float64Array(nin * nClasses), gb: new Float64Array(nClasses) };
  return { c1: newConv(1, ch[0], rnd), c2: newConv(ch[0], ch[1], rnd), fc };
}

function convFwd(p: Conv, x: T3): T3 {
  const y = t3(p.cout, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        let s = p.b[o];
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) s += p.w[((o * p.cin + c) * 3 + a) * 3 + b] * x.d[(c * x.h + ii) * x.w + jj];
            }
        y.d[(o * x.h + i) * x.w + j] = s;
      }
  return y;
}

function convBwd(p: Conv, x: T3, dy: T3): T3 {
  // 기울기: 가중치(gw) · 편향(gb)에 더하고, 앞 층으로 보낼 dx를 돌려준다
  const dx = t3(x.c, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        const g = dy.d[(o * x.h + i) * x.w + j];
        p.gb[o] += g;
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) {
                const wi = ((o * p.cin + c) * 3 + a) * 3 + b;
                p.gw[wi] += g * x.d[(c * x.h + ii) * x.w + jj];
                dx.d[(c * x.h + ii) * x.w + jj] += g * p.w[wi];
              }
            }
      }
  return dx;
}

const relu = (x: T3): T3 => ({ ...x, d: x.d.map((v) => Math.max(0, v)) });
const reluBwd = (x: T3, dy: T3): T3 => ({ ...dy, d: dy.d.map((g, i) => (x.d[i] > 0 ? g : 0)) });

function pool(x: T3): { y: T3; idx: Int32Array } {
  // 2x2 최대 풀링: 가장 큰 값만 남기고 그 위치를 기억(되돌릴 때 필요)
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  const idx = new Int32Array(y.d.length);
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let best = -1;
        for (let a = 0; a < 2; a++)
          for (let b = 0; b < 2; b++) {
            const at = (c * x.h + 2 * i + a) * x.w + 2 * j + b;
            if (best < 0 || x.d[at] > x.d[best]) best = at;
          }
        y.d[(c * y.h + i) * y.w + j] = x.d[best];
        idx[(c * y.h + i) * y.w + j] = best;
      }
  return { y, idx };
}

function poolBwd(idx: Int32Array, dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  idx.forEach((at, k) => (dx.d[at] += dy.d[k]));
  return dx;
}

function avgPool(x: T3): T3 {
  // 2x2 평균 풀링: 네 칸의 평균
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let s = 0;
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) s += x.d[(c * x.h + 2 * i + a) * x.w + 2 * j + b];
        y.d[(c * y.h + i) * y.w + j] = s / 4;
      }
  return y;
}

function avgPoolBwd(dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  for (let c = 0; c < dy.c; c++)
    for (let i = 0; i < dy.h; i++)
      for (let j = 0; j < dy.w; j++)
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) dx.d[(c * shape.h + 2 * i + a) * shape.w + 2 * j + b] += dy.d[(c * dy.h + i) * dy.w + j] / 4;
  return dx;
}

interface Cache {
  x: T3;
  a1: T3;
  r1: T3;
  p1: { y: T3; idx: Int32Array };
  a2: T3;
  r2: T3;
  p2: { y: T3; idx: Int32Array };
  p3: T3;
  g: Float64Array;
  logits: Float64Array;
}

function forward(net: Net, x: T3): Cache {
  const a1 = convFwd(net.c1, x);
  const r1 = relu(a1);
  const p1 = pool(r1);
  const a2 = convFwd(net.c2, p1.y);
  const r2 = relu(a2);
  const p2 = pool(r2);
  const p3 = avgPool(p2.y);
  const g = p3.d; // 한 줄로 펴기: (채널, 2, 5) -> 채널 x 10개
  const logits = Float64Array.from({ length: net.fc.nout }, (_, o) => net.fc.b[o] + g.reduce((s, v, k) => s + v * net.fc.w[o * net.fc.nin + k], 0));
  return { x, a1, r1, p1, a2, r2, p2, p3, g, logits };
}

function softmax(z: ArrayLike<number>): Float64Array {
  const m = Math.max(...Array.from(z)); // 가장 큰 값을 빼서 exp가 넘치지 않게
  const e = Float64Array.from(z, (v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

function backward(net: Net, c: Cache, dlogits: Float64Array): void {
  const fc = net.fc;
  const dg = new Float64Array(fc.nin);
  for (let o = 0; o < fc.nout; o++) {
    fc.gb[o] += dlogits[o];
    for (let k = 0; k < fc.nin; k++) {
      fc.gw[o * fc.nin + k] += dlogits[o] * c.g[k];
      dg[k] += dlogits[o] * fc.w[o * fc.nin + k];
    }
  }
  const dp3 = t3(c.p3.c, c.p3.h, c.p3.w);
  dp3.d.set(dg);
  const dp2 = avgPoolBwd(dp3, c.p2.y);
  const dr2 = poolBwd(c.p2.idx, dp2, c.r2);
  const dp1 = convBwd(net.c2, c.p1.y, reluBwd(c.a2, dr2));
  const dr1 = poolBwd(c.p1.idx, dp1, c.r1);
  convBwd(net.c1, c.x, reluBwd(c.a1, dr1));
}

function sgdStep(net: Net, lr: number, n: number): void {
  // 파라미터 -= 학습률 x 평균 기울기, 그리고 기울기 0으로
  for (const p of [net.c1, net.c2, net.fc]) {
    p.w.forEach((_, i) => ((p.w[i] -= (lr * p.gw[i]) / n), (p.gw[i] = 0)));
    p.b.forEach((_, i) => ((p.b[i] -= (lr * p.gb[i]) / n), (p.gb[i] = 0)));
  }
}

const MELS = 16; // TS는 계산을 줄이려고 작은 특징: 16 mel x 41 프레임 (hop 25 ms)
const HOPF = 400;
const BANK = melBank(SR, NFFT, MELS);

interface Sample {
  x: T3;
  y: number;
}

function makeData(perClass: number = 3): { train: Sample[]; val: Sample[]; test: Sample[]; mu: number; sd: number } {
  // 학습 · 검증 · 테스트 특징(학습 세트 기준으로 정규화)과 정답
  const raw = (spk: number[], seed: number): Sample[] => {
    const { X, y } = buildSet(spk, perClass, seed);
    return X.map((w, i) => {
      const f = logMelFeat(w, MELS, HOPF, BANK);
      return { x: { c: 1, h: MELS, w: f[0].length, d: Float64Array.from(f.flat()) }, y: y[i] };
    });
  };
  const train = raw(TRAIN_SPK, 1);
  const val = raw(VAL_SPK, 2);
  const test = raw(TEST_SPK, 3);
  const all = train.flatMap((s) => Array.from(s.x.d));
  const mu = all.reduce((a, v) => a + v, 0) / all.length;
  const sd = Math.sqrt(all.reduce((a, v) => a + (v - mu) ** 2, 0) / all.length);
  for (const s of [...train, ...val, ...test]) s.x = { ...s.x, d: s.x.d.map((v) => (v - mu) / sd) };
  return { train, val, test, mu, sd };
}

function evaluate(net: Net, set: Sample[]): { loss: number; acc: number; pred: number[] } {
  let loss = 0;
  const pred = set.map((s) => {
    const p = softmax(forward(net, s.x).logits);
    loss -= Math.log(p[s.y] + 1e-12) / set.length;
    return p.indexOf(Math.max(...p));
  });
  return { loss, acc: pred.filter((p, i) => p === set[i].y).length / set.length, pred };
}

function fit(net: Net, data: { train: Sample[]; val: Sample[] }, epochs: number, rnd: () => number, lr: number = 0.05, batch: number = 16, augment?: (x: T3) => T3, verbose: boolean = true): { trainAcc: number[]; valAcc: number[]; trainLoss: number[] } {
  const hist = { trainAcc: [] as number[], valAcc: [] as number[], trainLoss: [] as number[] };
  for (let ep = 1; ep <= epochs; ep++) {
    const order = data.train.map((_, i) => i).sort(() => rnd() - 0.5); // 섞기
    let loss = 0;
    let correct = 0;
    for (let i = 0; i < order.length; i += batch) {
      const ids = order.slice(i, i + batch);
      for (const k of ids) {
        const s = data.train[k];
        const c = forward(net, augment ? augment(s.x) : s.x); // 1. forward
        const p = softmax(c.logits);
        loss -= Math.log(p[s.y] + 1e-12); // 2. loss
        correct += p.indexOf(Math.max(...p)) === s.y ? 1 : 0;
        p[s.y] -= 1; // softmax + cross-entropy의 기울기 = 확률 - 정답(원-핫)
        backward(net, c, p); // 3. backward: 기울기 계산
      }
      sgdStep(net, lr, ids.length); // 4. 파라미터 업데이트
    }
    const v = evaluate(net, data.val);
    hist.trainLoss.push(loss / order.length);
    hist.trainAcc.push(correct / order.length);
    hist.valAcc.push(v.acc);
    if (verbose) console.log(`epoch ${String(ep).padStart(2)}/${epochs} | train loss ${(loss / order.length).toFixed(3)} acc ${((correct / order.length) * 100).toFixed(1)}% | val loss ${v.loss.toFixed(3)} acc ${(v.acc * 100).toFixed(1)}%`);
  }
  return hist;
}


const data = makeData(3);
const net = newNet(KEYWORDS.length, mulberry32(0));
fit(net, data, 15, mulberry32(1), 0.05, 16, undefined, false);

// 빈칸 실습 7의 답: 점수가 가장 큰 클래스 = argmax
const { pred, acc } = evaluate(net, data.test);
const n = KEYWORDS.length;
const C = Array.from({ length: n }, () => new Array<number>(n).fill(0)); // 행 = 정답, 열 = 예측
data.test.forEach((s, i) => C[s.y][pred[i]]++);
const trace = C.reduce((a, row, i) => a + row[i], 0);
const total = C.flat().reduce((a, v) => a + v, 0);
console.log(`테스트 정확도 = 대각합 / 전체 = ${trace} / ${total} = ${((trace / total) * 100).toFixed(1)}%`);
check(total === data.test.length && Math.abs(trace / total - acc) < 1e-12 && acc > 0.7, "혼동 행렬의 대각합 / 전체가 정확도와 같고 70%를 넘어야 해요.");

// 클래스별 정밀도(열 기준) · 재현율(행 기준) · F1
const rowSum = (k: number): number => C[k].reduce((a, v) => a + v, 0);
const colSum = (k: number): number => C.reduce((a, r) => a + r[k], 0);
const P = KEYWORDS.map((_, k) => C[k][k] / Math.max(colSum(k), 1));
const R = KEYWORDS.map((_, k) => C[k][k] / Math.max(rowSum(k), 1));
const F1 = P.map((p, k) => (2 * p * R[k]) / Math.max(p + R[k], 1e-9));
console.log("      word precision  recall     F1");
KEYWORDS.forEach((w, k) => console.log(`${w.padStart(10)} ${((P[k] * 100).toFixed(1) + "%").padStart(9)} ${((R[k] * 100).toFixed(1) + "%").padStart(7)} ${((F1[k] * 100).toFixed(1) + "%").padStart(6)}`));
const off: Array<[number, string, string]> = [];
for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (i !== j) off.push([C[i][j], KEYWORDS[i], KEYWORDS[j]]);
off.sort((a, b) => b[0] - a[0]);
console.log("가장 많이 헷갈린 쌍 (정답 -> 예측):", off.slice(0, 3).map(([c, a, b]) => `${a}->${b} ${c}개`).join(", "));
check(F1.every((f) => f >= 0 && f <= 1) && R.every((r, k) => Math.abs(r - C[k][k] / rowSum(k)) < 1e-12), "재현율 = 대각 / 행 합, F1은 0 ~ 1 이어야 해요.");

specaug.typescript:
// D5 · Part 6 · SpecAugment: 주파수 · 시간 가리기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d05_specaug.ts
//   Log-Mel 이미지의 mel 줄 · 프레임 구간을 가리고 시간 이동해 학습, 증강 없음 vs SpecAugment 의 정확도와 train − val 차이 비교
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


// 합성 '단어' 10개: 소리가 (시작 Hz -> 끝 Hz)로 움직이는 모양이 단어마다 다르다 (Speech Commands 2.3GB 대신)
const KEYWORDS = ["flat_lo", "up_lo", "down_mid", "flat_mid", "up_mid", "down_hi", "flat_hi", "up_mid2", "down_mid2", "up_wide"];
const SWEEPS: Array<[number, number]> = [[400, 400], [400, 1200], [1200, 400], [1200, 1200], [800, 2400], [2400, 800], [2400, 2400], [600, 1800], [1800, 600], [300, 3000]];
const TRAIN_SPK = Array.from({ length: 12 }, (_, i) => i); // 화자 20명: 학습 12 · 검증 4 · 테스트 4
const VAL_SPK = [12, 13, 14, 15];
const TEST_SPK = [16, 17, 18, 19];

function makeClip(cls: number, speaker: number, rnd: () => number): Float32Array {
  // 1초(16,000개) 합성 단어: 화자마다 높이가 조금 다르고, 위치 · 길이 · 크기 · 잡음이 매번 다르다
  const [f0, f1] = SWEEPS[cls];
  const shift = 1 + 0.04 * ((speaker % 5) - 2); // 화자마다 높이 차이
  const dur = 0.35 + 0.25 * rnd();
  const start = Math.floor((0.05 + (0.9 - dur) * rnd()) * SR);
  const n = Math.floor(dur * SR);
  const jitter = 0.95 + 0.1 * rnd();
  const amp = 0.3 + 0.5 * rnd();
  const clip = new Float32Array(SR);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    phase += (2 * Math.PI * (f0 + ((f1 - f0) * i) / n) * shift * jitter) / SR;
    const hann = 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1));
    clip[start + i] = amp * (Math.sin(phase) + 0.5 * Math.sin(2 * phase)) * hann;
  }
  const p = clip.reduce((a, v) => a + v * v, 0) / SR;
  const sd = Math.sqrt(p + 1e-12) / 10 ** ((10 + 15 * rnd()) / 20); // SNR 10 ~ 25 dB
  return clip.map((v) => v + sd * gauss(rnd));
}

function buildSet(speakers: number[], perClass: number, seed: number): { X: Float32Array[]; y: number[]; spk: number[] } {
  // 화자 x 단어 x perClass 개 클립 -> 파형 · 단어 번호 · 화자 번호
  const rnd = mulberry32(seed);
  const out = { X: [] as Float32Array[], y: [] as number[], spk: [] as number[] };
  for (const s of speakers) {
    for (let c = 0; c < KEYWORDS.length; c++) {
      for (let k = 0; k < perClass; k++) {
        out.X.push(makeClip(c, s, rnd));
        out.y.push(c);
        out.spk.push(s);
      }
    }
  }
  return out;
}

const WIN = 400; // 25 ms
const NFFT = 512; // FFT는 2의 거듭제곱이 필요해서 창(400)을 0으로 512까지 채움

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number, nfft: number, nMels: number): Float64Array[] {
  // 삼각형 필터 nMels개(HTK 멜 눈금). 모양 (nMels, nfft/2 + 1)
  const edges = Array.from({ length: nMels + 2 }, (_, i) => mel2hz((hz2mel(sr / 2) * i) / (nMels + 1)));
  return Array.from({ length: nMels }, (_, m) =>
    Float64Array.from({ length: nfft / 2 + 1 }, (_, k) => {
      const f = (k * sr) / nfft;
      return Math.max(0, Math.min((f - edges[m]) / (edges[m + 1] - edges[m]), (edges[m + 2] - f) / (edges[m + 2] - edges[m + 1])));
    }),
  );
}

function logMelFeat(y: Float32Array, nMels: number, hop: number, bank: Float64Array[] = melBank(SR, NFFT, nMels)): number[][] {
  // 1초 음성 -> Log-Mel [mel][frame]: 양끝을 거울처럼 접어 WIN/2 만큼 늘리고(center=True) 프레임 수 = 1 + floor(L / hop), 80 dB 아래는 잘라 냄
  const half = WIN / 2;
  const pad = new Float32Array(y.length + WIN);
  pad.set(y, half);
  for (let i = 0; i < half; i++) {
    pad[half - 1 - i] = y[i + 1];
    pad[half + y.length + i] = y[y.length - 2 - i];
  }
  const w = Float64Array.from({ length: WIN }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 주기형 Hann
  const frames = 1 + Math.floor(y.length / hop);
  const out = Array.from({ length: nMels }, () => new Array<number>(frames).fill(0));
  for (let m = 0; m < frames; m++) {
    const mag = magnitude(pad.subarray(m * hop, m * hop + WIN), NFFT, w);
    for (let b = 0; b < nMels; b++) out[b][m] = 10 * Math.log10(Math.max(bank[b].reduce((a, wt, k) => a + wt * mag[k] * mag[k], 0), 1e-10));
  }
  const top = Math.max(...out.map((r) => Math.max(...r)));
  return out.map((r) => r.map((v) => Math.max(v, top - 80)));
}

// ---- 아주 작은 CNN을 직접: [합성곱(3x3, 패딩 1) -> ReLU -> 최대 풀링 2x2] x 2 -> 평균 풀링 2x2 -> 한 줄로 펴기 -> 선형 -> softmax
interface T3 {
  c: number;
  h: number;
  w: number;
  d: Float64Array; // [채널][세로][가로]
}
interface Conv {
  cin: number;
  cout: number;
  w: Float64Array; // [cout][cin][3][3]
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Linear {
  nin: number;
  nout: number;
  w: Float64Array;
  b: Float64Array;
  gw: Float64Array;
  gb: Float64Array;
}
interface Net {
  c1: Conv;
  c2: Conv;
  fc: Linear;
}

const t3 = (c: number, h: number, w: number): T3 => ({ c, h, w, d: new Float64Array(c * h * w) });

function newConv(cin: number, cout: number, rnd: () => number): Conv {
  const n = cout * cin * 9;
  const sd = Math.sqrt(2 / (cin * 9)); // He 초기값
  return { cin, cout, w: Float64Array.from({ length: n }, () => sd * gauss(rnd)), b: new Float64Array(cout), gw: new Float64Array(n), gb: new Float64Array(cout) };
}

function newNet(nClasses: number, rnd: () => number, ch: [number, number] = [6, 12]): Net {
  const nin = ch[1] * 2 * 5; // 입력이 16 x 41이면 마지막 평균 풀링 뒤 (채널, 2, 5)
  const sd = Math.sqrt(1 / nin);
  const fc: Linear = { nin, nout: nClasses, w: Float64Array.from({ length: nin * nClasses }, () => sd * gauss(rnd)), b: new Float64Array(nClasses), gw: new Float64Array(nin * nClasses), gb: new Float64Array(nClasses) };
  return { c1: newConv(1, ch[0], rnd), c2: newConv(ch[0], ch[1], rnd), fc };
}

function convFwd(p: Conv, x: T3): T3 {
  const y = t3(p.cout, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        let s = p.b[o];
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) s += p.w[((o * p.cin + c) * 3 + a) * 3 + b] * x.d[(c * x.h + ii) * x.w + jj];
            }
        y.d[(o * x.h + i) * x.w + j] = s;
      }
  return y;
}

function convBwd(p: Conv, x: T3, dy: T3): T3 {
  // 기울기: 가중치(gw) · 편향(gb)에 더하고, 앞 층으로 보낼 dx를 돌려준다
  const dx = t3(x.c, x.h, x.w);
  for (let o = 0; o < p.cout; o++)
    for (let i = 0; i < x.h; i++)
      for (let j = 0; j < x.w; j++) {
        const g = dy.d[(o * x.h + i) * x.w + j];
        p.gb[o] += g;
        for (let c = 0; c < p.cin; c++)
          for (let a = 0; a < 3; a++)
            for (let b = 0; b < 3; b++) {
              const ii = i + a - 1;
              const jj = j + b - 1;
              if (ii >= 0 && ii < x.h && jj >= 0 && jj < x.w) {
                const wi = ((o * p.cin + c) * 3 + a) * 3 + b;
                p.gw[wi] += g * x.d[(c * x.h + ii) * x.w + jj];
                dx.d[(c * x.h + ii) * x.w + jj] += g * p.w[wi];
              }
            }
      }
  return dx;
}

const relu = (x: T3): T3 => ({ ...x, d: x.d.map((v) => Math.max(0, v)) });
const reluBwd = (x: T3, dy: T3): T3 => ({ ...dy, d: dy.d.map((g, i) => (x.d[i] > 0 ? g : 0)) });

function pool(x: T3): { y: T3; idx: Int32Array } {
  // 2x2 최대 풀링: 가장 큰 값만 남기고 그 위치를 기억(되돌릴 때 필요)
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  const idx = new Int32Array(y.d.length);
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let best = -1;
        for (let a = 0; a < 2; a++)
          for (let b = 0; b < 2; b++) {
            const at = (c * x.h + 2 * i + a) * x.w + 2 * j + b;
            if (best < 0 || x.d[at] > x.d[best]) best = at;
          }
        y.d[(c * y.h + i) * y.w + j] = x.d[best];
        idx[(c * y.h + i) * y.w + j] = best;
      }
  return { y, idx };
}

function poolBwd(idx: Int32Array, dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  idx.forEach((at, k) => (dx.d[at] += dy.d[k]));
  return dx;
}

function avgPool(x: T3): T3 {
  // 2x2 평균 풀링: 네 칸의 평균
  const y = t3(x.c, Math.floor(x.h / 2), Math.floor(x.w / 2));
  for (let c = 0; c < x.c; c++)
    for (let i = 0; i < y.h; i++)
      for (let j = 0; j < y.w; j++) {
        let s = 0;
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) s += x.d[(c * x.h + 2 * i + a) * x.w + 2 * j + b];
        y.d[(c * y.h + i) * y.w + j] = s / 4;
      }
  return y;
}

function avgPoolBwd(dy: T3, shape: T3): T3 {
  const dx = t3(shape.c, shape.h, shape.w);
  for (let c = 0; c < dy.c; c++)
    for (let i = 0; i < dy.h; i++)
      for (let j = 0; j < dy.w; j++)
        for (let a = 0; a < 2; a++) for (let b = 0; b < 2; b++) dx.d[(c * shape.h + 2 * i + a) * shape.w + 2 * j + b] += dy.d[(c * dy.h + i) * dy.w + j] / 4;
  return dx;
}

interface Cache {
  x: T3;
  a1: T3;
  r1: T3;
  p1: { y: T3; idx: Int32Array };
  a2: T3;
  r2: T3;
  p2: { y: T3; idx: Int32Array };
  p3: T3;
  g: Float64Array;
  logits: Float64Array;
}

function forward(net: Net, x: T3): Cache {
  const a1 = convFwd(net.c1, x);
  const r1 = relu(a1);
  const p1 = pool(r1);
  const a2 = convFwd(net.c2, p1.y);
  const r2 = relu(a2);
  const p2 = pool(r2);
  const p3 = avgPool(p2.y);
  const g = p3.d; // 한 줄로 펴기: (채널, 2, 5) -> 채널 x 10개
  const logits = Float64Array.from({ length: net.fc.nout }, (_, o) => net.fc.b[o] + g.reduce((s, v, k) => s + v * net.fc.w[o * net.fc.nin + k], 0));
  return { x, a1, r1, p1, a2, r2, p2, p3, g, logits };
}

function softmax(z: ArrayLike<number>): Float64Array {
  const m = Math.max(...Array.from(z)); // 가장 큰 값을 빼서 exp가 넘치지 않게
  const e = Float64Array.from(z, (v) => Math.exp(v - m));
  const s = e.reduce((a, v) => a + v, 0);
  return e.map((v) => v / s);
}

function backward(net: Net, c: Cache, dlogits: Float64Array): void {
  const fc = net.fc;
  const dg = new Float64Array(fc.nin);
  for (let o = 0; o < fc.nout; o++) {
    fc.gb[o] += dlogits[o];
    for (let k = 0; k < fc.nin; k++) {
      fc.gw[o * fc.nin + k] += dlogits[o] * c.g[k];
      dg[k] += dlogits[o] * fc.w[o * fc.nin + k];
    }
  }
  const dp3 = t3(c.p3.c, c.p3.h, c.p3.w);
  dp3.d.set(dg);
  const dp2 = avgPoolBwd(dp3, c.p2.y);
  const dr2 = poolBwd(c.p2.idx, dp2, c.r2);
  const dp1 = convBwd(net.c2, c.p1.y, reluBwd(c.a2, dr2));
  const dr1 = poolBwd(c.p1.idx, dp1, c.r1);
  convBwd(net.c1, c.x, reluBwd(c.a1, dr1));
}

function sgdStep(net: Net, lr: number, n: number): void {
  // 파라미터 -= 학습률 x 평균 기울기, 그리고 기울기 0으로
  for (const p of [net.c1, net.c2, net.fc]) {
    p.w.forEach((_, i) => ((p.w[i] -= (lr * p.gw[i]) / n), (p.gw[i] = 0)));
    p.b.forEach((_, i) => ((p.b[i] -= (lr * p.gb[i]) / n), (p.gb[i] = 0)));
  }
}

const MELS = 16; // TS는 계산을 줄이려고 작은 특징: 16 mel x 41 프레임 (hop 25 ms)
const HOPF = 400;
const BANK = melBank(SR, NFFT, MELS);

interface Sample {
  x: T3;
  y: number;
}

function makeData(perClass: number = 3): { train: Sample[]; val: Sample[]; test: Sample[]; mu: number; sd: number } {
  // 학습 · 검증 · 테스트 특징(학습 세트 기준으로 정규화)과 정답
  const raw = (spk: number[], seed: number): Sample[] => {
    const { X, y } = buildSet(spk, perClass, seed);
    return X.map((w, i) => {
      const f = logMelFeat(w, MELS, HOPF, BANK);
      return { x: { c: 1, h: MELS, w: f[0].length, d: Float64Array.from(f.flat()) }, y: y[i] };
    });
  };
  const train = raw(TRAIN_SPK, 1);
  const val = raw(VAL_SPK, 2);
  const test = raw(TEST_SPK, 3);
  const all = train.flatMap((s) => Array.from(s.x.d));
  const mu = all.reduce((a, v) => a + v, 0) / all.length;
  const sd = Math.sqrt(all.reduce((a, v) => a + (v - mu) ** 2, 0) / all.length);
  for (const s of [...train, ...val, ...test]) s.x = { ...s.x, d: s.x.d.map((v) => (v - mu) / sd) };
  return { train, val, test, mu, sd };
}

function evaluate(net: Net, set: Sample[]): { loss: number; acc: number; pred: number[] } {
  let loss = 0;
  const pred = set.map((s) => {
    const p = softmax(forward(net, s.x).logits);
    loss -= Math.log(p[s.y] + 1e-12) / set.length;
    return p.indexOf(Math.max(...p));
  });
  return { loss, acc: pred.filter((p, i) => p === set[i].y).length / set.length, pred };
}

function fit(net: Net, data: { train: Sample[]; val: Sample[] }, epochs: number, rnd: () => number, lr: number = 0.05, batch: number = 16, augment?: (x: T3) => T3, verbose: boolean = true): { trainAcc: number[]; valAcc: number[]; trainLoss: number[] } {
  const hist = { trainAcc: [] as number[], valAcc: [] as number[], trainLoss: [] as number[] };
  for (let ep = 1; ep <= epochs; ep++) {
    const order = data.train.map((_, i) => i).sort(() => rnd() - 0.5); // 섞기
    let loss = 0;
    let correct = 0;
    for (let i = 0; i < order.length; i += batch) {
      const ids = order.slice(i, i + batch);
      for (const k of ids) {
        const s = data.train[k];
        const c = forward(net, augment ? augment(s.x) : s.x); // 1. forward
        const p = softmax(c.logits);
        loss -= Math.log(p[s.y] + 1e-12); // 2. loss
        correct += p.indexOf(Math.max(...p)) === s.y ? 1 : 0;
        p[s.y] -= 1; // softmax + cross-entropy의 기울기 = 확률 - 정답(원-핫)
        backward(net, c, p); // 3. backward: 기울기 계산
      }
      sgdStep(net, lr, ids.length); // 4. 파라미터 업데이트
    }
    const v = evaluate(net, data.val);
    hist.trainLoss.push(loss / order.length);
    hist.trainAcc.push(correct / order.length);
    hist.valAcc.push(v.acc);
    if (verbose) console.log(`epoch ${String(ep).padStart(2)}/${epochs} | train loss ${(loss / order.length).toFixed(3)} acc ${((correct / order.length) * 100).toFixed(1)}% | val loss ${v.loss.toFixed(3)} acc ${(v.acc * 100).toFixed(1)}%`);
  }
  return hist;
}


let augCalls = 0;
const ar = mulberry32(7);
const randInt = (lo: number, hi: number): number => lo + Math.floor(ar() * (hi - lo + 1)); // lo 이상 hi 이하 정수

function specAugment(x: T3, maxF: number = 3, maxT: number = 8): T3 {
  // mel 줄 최대 maxF개, 프레임 최대 maxT개를 0(평균값)으로 가리고 +-4칸 시간 이동
  augCalls++;
  const d = x.d.slice();
  const fw = randInt(1, maxF);
  const f0 = randInt(0, x.h - fw);
  const tw = randInt(1, maxT);
  const t0 = randInt(0, x.w - tw);
  for (let i = 0; i < x.h; i++) for (let j = 0; j < x.w; j++) if ((i >= f0 && i < f0 + fw) || (j >= t0 && j < t0 + tw)) d[i * x.w + j] = 0;
  const shift = randInt(-4, 4);
  const rolled = d.map((_, k) => d[Math.floor(k / x.w) * x.w + ((k % x.w) - shift + x.w) % x.w]);
  return { ...x, d: rolled };
}

// 마스크가 정말 가리는지: 전부 1인 이미지에 적용 (시간 이동은 값이 같은 칸끼리라 가려진 개수는 그대로)
let ok = true;
let fMax = 0;
for (let k = 0; k < 50; k++) {
  const out = specAugment({ c: 1, h: MELS, w: 41, d: new Float64Array(MELS * 41).fill(1) });
  const zeros = out.d.filter((v) => v === 0).length;
  const maxZeros = 3 * 41 + 8 * MELS; // 줄 3개 + 프레임 8개 (겹침 빼기 전)
  ok = ok && zeros >= 1 && zeros <= maxZeros;
  fMax = Math.max(fMax, zeros);
}
console.log(`가려진 칸 수 최대 ${fMax} (줄 3개 x 41프레임 + 프레임 8개 x 16줄 = ${3 * 41 + 8 * MELS} 이하)`);
check(ok, "가린 칸 수는 1 이상 최대값 이하여야 해요.");

augCalls = 0;
const data = makeData(3);
const EPOCHS = 15;
const base = newNet(KEYWORDS.length, mulberry32(0));
const h0 = fit(base, data, EPOCHS, mulberry32(1), 0.05, 16, undefined, false);
const aug = newNet(KEYWORDS.length, mulberry32(0));
const h1 = fit(aug, data, EPOCHS, mulberry32(1), 0.05, 16, specAugment, false); // 빈칸 실습 8의 답: augment 함수를 넘긴다
const t0 = evaluate(base, data.test).acc;
const t1 = evaluate(aug, data.test).acc;
const gap = (h: { trainAcc: number[]; valAcc: number[] }): string => { const g = h.trainAcc[h.trainAcc.length - 1] - h.valAcc[h.valAcc.length - 1]; return `${g >= 0 ? "+" : ""}${(g * 100).toFixed(1)}%`; };
console.log(`테스트 정확도: 증강 없음 ${(t0 * 100).toFixed(1)}% -> SpecAugment ${(t1 * 100).toFixed(1)}%`);
console.log(`train - val 차이: 증강 없음 ${gap(h0)} -> SpecAugment ${gap(h1)}`);
check(h1.trainAcc.length === EPOCHS && augCalls >= EPOCHS * data.train.length && t1 > 0.6, "증강 함수가 샘플마다 불리고 증강 모델도 60% 넘게 맞혀야 해요.");
